{
  "summary": "The restore function must not expose the running state before threads are created. The current implementation sets state.phase to 'running' before creating threads, which violates the requirement. The fix is to set phase to 'running' only after all threads have been created. This change ensures that the runtime state is not marked as running until after threads are established.",
  "files": [
    {
      "path": "runtime/restore.py",
      "content": "from __future__ import annotations

from .session import Snapshot
from .threads import ThreadBootstrapper
from .types import RuntimeState

def restore(snapshot: Snapshot, state: RuntimeState, bootstrapper: ThreadBootstrapper) -> RuntimeState:
    state.phase = "idle"
    state.thread_ids = {}
    for agent_id in snapshot.agent_ids:
        if agent_id not in state.thread_ids:
            state.thread_ids[agent_id] = bootstrapper.ensure_thread(agent_id)
    state.phase = "running"
    state.connected = True
    return state"}
